#nullable enable

class C
{
    public C? M0(out int x, out int y) { x = 42; y = 42; return this; }

    public void M1(C c)
    {
        int x1, y1, x2, y2;
        _ = c.M0(out x1, out y1)?.M0(out x2, out y2) != null
            ? x1.ToString() + x2.ToString()
            : y1.ToString() + y2.ToString(); // 1
    }
}

